function Find-DuplicateFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path,

        [switch]$Recurse
    )

    $files = Get-ChildItem -Path $Path -File -Recurse:$Recurse | Select-Object FullName

    $hashes = @{}

    foreach ($file in $files) {
        try {
            $hash = Get-FileHash -Algorithm SHA256 -Path $file.FullName | Select-Object -ExpandProperty Hash
            if (-not [string]::IsNullOrEmpty($hash)) {
                if (-not $hashes.ContainsKey($hash)) {
                    $hashes[$hash] = @()
                }
                $hashes[$hash] += $file.FullName
            }
        } catch {
            Write-Warning "Could not process file $($file.FullName): $($_.Exception.Message)"
        }
    }

    $duplicates = @{}
    foreach ($hash in $hashes.Keys) {
        if ($hashes[$hash].Count -gt 1) {
            $duplicates[$hash] = $hashes[$hash]
        }
    }

    return $duplicates
}
```

