using System;
using System.Collections.Generic;

public class ThreadSafeLruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<CacheEntry<TKey, TValue>>> _cacheMap;
    private readonly LinkedList<CacheEntry<TKey, TValue>> _lruList;
    private readonly object _lock = new object();

    private class CacheEntry<TKey, TValue>
    {
        public TKey Key { get; set; }
        public TValue Value { get; set; }
    }

    public ThreadSafeLruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentException("Capacity must be positive.");
        _capacity = capacity;
        _cacheMap = new Dictionary<TKey, LinkedListNode<CacheEntry<TKey, TValue>>>();
        _lruList = new LinkedList<CacheEntry<TKey, TValue>>();
    }

    public bool Get(TKey key, out TValue value)
    {
        lock (_lock)
        {
            if (!_cacheMap.TryGetValue(key, out var node))
            {
                value = default;
                return false;
            }

            // Move accessed item to the front (most recently used)
            _lruList.Remove(node);
            _lruList.AddFirst(node);
            value = node.Value.Value;
            return true;
        }
    }

    public void Put(TKey key, TValue value)
    {
        lock (_lock)
        {
            if (_cacheMap.TryGetValue(key, out var node))
            {
                // Update existing item and move to front
                node.Value.Value = value;
                _lruList.Remove(node);
                _lruList.AddFirst(node);
            }
            else
            {
                if (_cacheMap.Count >= _capacity)
                {
                    // Evict the least recently used item (tail of the list)
                    var lruNode = _lruList.Last;
                    if (lruNode != null)
                    {
                        _cacheMap.Remove(lruNode.Value.Key);
                        _lruList.RemoveLast();
                    }
                }

                // Add new item to the front
                var newNode = _lruList.AddFirst(new CacheEntry<TKey, TValue> { Key = key, Value = value });
                _cacheMap[key] = newNode;
            }
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        var cache = new ThreadSafeLruCache<string, int>(3);

        // Put items
        cache.Put("A", 10);
        cache.Put("B", 20);
        cache.Put("C", 30);

        Console.WriteLine($"Get A: {cache.Get("A", out var valA)} -> {valA}"); // Access A, moves to front
        cache.Put("D", 40); // Evicts B (LRU)

        // Check eviction
        if (!cache.Get("B", out _))
        {
            Console.WriteLine("B was evicted successfully.");
        }

        // Test capacity and ordering: Current order should be D, A, C
        cache.Put("E", 50); // Evicts C (LRU)

        if (!cache.Get("C", out _))
        {
            Console.WriteLine("C was evicted successfully.");
        }

        // Test update and move to front
        cache.Put("A", 100);
        Console.WriteLine($"Get A after update: {cache.Get("A", out var valA)} -> {valA}"); // Should be 100
    }
}
