public class RetryHelper
{
    private const int MaxRetries = 3;
    private const int DelayMilliseconds = 1000;

    public static T RetryAction<T>(Func<T> action)
    {
        for (int attempt = 1; attempt <= MaxRetries; attempt++)
        {
            try
            {
                return action();
            }
            catch (Exception ex)
            {
                if (attempt == MaxRetries)
                {
                    Console.WriteLine($"Final failure on attempt {attempt}. Exception type: {ex.GetType().Name}");
                    throw; // Re-throw the last exception if all retries fail
                }

                Console.WriteLine($"Attempt {attempt} failed. Exception type: {ex.GetType().Name}. Retrying in {DelayMilliseconds}ms...");
                Thread.Sleep(DelayMilliseconds);
            }
        }
        // This line should technically be unreachable if MaxRetries >= 1, but required for compiler path coverage
        throw new InvalidOperationException("Retry logic failed to complete.");
    }

    public static void Main(string[] args)
    {
        int counter = 0;
        Func<int> failingAction = () => {
            counter++;
            if (counter < 3)
            {
                throw new InvalidOperationException("Simulated transient error.");
            }
            return 42; // Success on the third attempt
        };

        try
        {
            int result = RetryAction(failingAction);
            Console.WriteLine($"Success! Result: {result}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Operation ultimately failed after all retries. Final error: {ex.GetType().Name}");
        }

        // Example of guaranteed failure
        Func<int> alwaysFailingAction = () => throw new ArgumentNullException("Always fails.");
        try
        {
            RetryAction(alwaysFailingAction);
        }
        catch (Exception)
        {
            Console.WriteLine("\nSuccessfully caught the final exception from the guaranteed failure test.");
        }
    }
}
