const processId = async (id) => {
  // Simulate asynchronous work
  await new Promise(resolve => setTimeout(resolve, Math.random() * 100));
  return `Processed ${id}`;
};

async function runWorkerPool(ids, concurrency) {
  const results = [];
  const runningPromises = new Set();
  let index = 0;

  while (index < ids.length || runningPromises.size > 0) {
    if (runningPromises.size < concurrency && index < ids.length) {
      const currentId = ids[index];
      const promise = processId(currentId).then(result => {
        results.push(result);
        runningPromises.delete(promise);
      });
      runningPromises.add(promise);
      index++;
    } else if (runningPromises.size > 0) {
      // Wait for at least one running promise to finish before checking again
      await Promise.race(Array.from(runningPromises));
    }
  }
  return results;
}

const ids = Array.from({ length: 100 }, (_, i) => i + 1);
runWorkerPool(ids, 4).then(results => {
  console.log(results);
});
