const bufferSize = 64 * 1024; // Read in 64KB chunks

function countTimeouts(path) {
    try {
        const fd = fs.openSync(path, 'r');
        const buffer = Buffer.alloc(bufferSize);
        let bytesRead;
        let currentLineBuffer = '';

        while ((bytesRead = fs.readSync(fd, buffer, 0, bufferSize)) > 0) {
            const chunk = buffer.slice(0, bytesRead).toString('utf8');
            const combinedData = currentLineBuffer + chunk;

            let lastNewlineIndex = -1;
            while ((lastNewlineIndex = combinedData.lastIndexOf('\n')) !== -1) {
                const line = combinedData.substring(0, lastNewlineIndex);
                if (line.includes('Timeout')) {
                    timeoutCount++;
                }
                currentLineBuffer = combinedData.substring(lastNewlineIndex + 1);
            }
        }

        // Check for any remaining content that doesn't end with a newline
        const lastLine = currentLineBuffer;
        if (lastLine.length > 0 && lastLine.includes('Timeout')) {
            timeoutCount++;
        }

        fs.closeSync(fd);
        console.log(`Total lines containing 'Timeout': ${timeoutCount}`);

    } catch (err) {
        console.error('Error processing file:', err);
    }
}

countTimeouts(filePath);
