function Convert-CsvToJson {
    param(
        [Parameter(Mandatory=$true)]
        [string]$CsvPath,

        [int]$Depth = 5
    )

    $data = Import-Csv -Path $CsvPath

    # Simple recursive function to handle nesting up to the specified depth
    function Convert-ObjectToNestedJson {
        param(
            $obj,
            $currentDepth
        )
        if ($currentDepth -gt $Depth) {
            return $obj # Stop nesting further
        }

        $nestedObj = @{}
        foreach ($prop in $obj.PSObject.Properties) {
            $value = $prop.Value
            if ($value -is [hashtable] -or $value -is [psobject]) {
                # Recursively call for objects/hashtables
                $nestedObj[$prop.Name] = Convert-ObjectToNestedJson -obj $value -currentDepth ($currentDepth + 1)
            } elseif ($value -is [array]) {
                # Handle arrays by mapping elements recursively if they are complex objects
                $nestedArray = @()
                foreach ($item in $value) {
                    if ($item -is [hashtable] -or $item -is [psobject]) {
                        $nestedArray += Convert-ObjectToNestedJson -obj $item -currentDepth ($currentDepth + 1)
                    } else {
                        $nestedArray += $item # Keep primitives as is in arrays
                    }
                }
                $nestedObj[$prop.Name] = $nestedArray
            } else {
                # Primitive type
                $nestedObj[$prop.Name] = $value
            }
        }
        return $nestedObj
    }

    $jsonOutput = @()
    foreach ($item in $data) {
        $jsonOutput += Convert-ObjectToNestedJson -obj $item -currentDepth 1
    }

    # Convert the array of objects to a JSON string with formatting
    $jsonString = $jsonOutput | ConvertTo-Json -Depth 5
    return $jsonString
}

# Example usage:
# $csvFilePath = "your_input.csv"
# $jsonResult = Convert-CsvToJson -CsvPath $csvFilePath -Depth 5
# Write-Host $jsonResult
```

