function Find-DuplicateFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [switch]$Recurse
    )

    Set-StrictMode -Version 2.0
    $ErrorActionPreference = 'Stop'

    try {
        $files = Get-ChildItem -Path $Path -File -Recurse:$Recurse -ErrorAction Stop
        $hashes = @{}

        foreach ($file in $files) {
            $hashValue = Get-FileHash -Path $file.FullName -Algorithm SHA256 | Select-Object -ExpandProperty Hash
            if (-not $hashes.ContainsKey($hashValue)) {
                $hashes[$hashValue] = @()
            }
            $hashes[$hashValue] += $file.FullName
        }

        $duplicates = @{}
        foreach ($hash in $hashes.Keys) {
            if ($hashes[$hash].Count -gt 1) {
                $duplicates[$hash] = $hashes[$hash]
            }
        }

        return $duplicates
    }
    catch {
        Write-Error ("Failed: " + $_.Exception.Message)
        exit 1
    }
}
