using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide a file path as an argument.");
            return;
        }

        string path = args[0];
        if (!File.Exists(path))
        {
            Console.WriteLine("The specified file does not exist.");
            return;
        }

        Dictionary<string, int> wordCounts = new Dictionary<string, int>();

        try
        {
            // Use File.ReadLines to stream the file line by line for memory efficiency
            foreach (string line in File.ReadLines(path))
            {
                // Simple tokenization: find sequences of letters and convert to lower case for counting
                MatchCollection matches = Regex.Matches(line, @"[a-zA-Z]+");

                foreach (Match match in matches)
                {
                    string word = match.Value;
                    if (wordCounts.ContainsKey(word))
                    {
                        wordCounts[word]++;
                    }
                    else
                    {
                        wordCounts[word] = 1;
                    }
                }
            }

            // Sort and take the top 10 most frequent words
            var topWords = wordCounts.OrderByDescending(pair => pair.Value)
                                     .Take(10);

            Console.WriteLine("Top 10 Most Frequent Words:");
            foreach (var item in topWords)
            {
                Console.WriteLine("{0}: {1}", item.Key, item.Value);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred while processing the file: " + ex.Message);
        }
    }
}
