using System;
using System.Collections.Generic;
using System.Linq;

class Order
{
    public string Customer { get; set; }
    public decimal Amount { get; set; }

    public Order(string customer, decimal amount)
    {
        Customer = customer;
        Amount = amount;
    }
}

class Program
{
    static void Main(string[] args)
    {
        List<Order> orders = new List<Order>
        {
            new Order("Ann", 10.5m),
            new Order("Bob", 3m),
            new Order("Ann", 7m),
            new Order("Charlie", 25.0m)
        };

        // Calculate total per customer and sort by total descending
        var totals = orders.GroupBy(o => o.Customer)
                           .Select(g => new { Customer = g.Key, Total = g.Sum(o => o.Amount) })
                           .OrderByDescending(t => t.Total);

        Console.WriteLine("--- Customer Totals (Highest First) ---");
        foreach (var t in totals)
        {
            Console.WriteLine("{0}: {1:C}", t.Customer, t.Total);
        }

        // Find the single biggest order overall
        Order biggestOrder = orders.OrderByDescending(o => o.Amount).First();

        Console.WriteLine("\n--- Single Biggest Order ---");
        Console.WriteLine("{0}: {1:C}", biggestOrder.Customer, biggestOrder.Amount);
    }
}
