                Console.WriteLine($"Attempt {attempt} started.");
                if (attempt < 3)
                {
                    throw new InvalidOperationException("Simulated failure");
                }
                Console.WriteLine("Action succeeded on attempt " + attempt);
                return true;
            }, 3, TimeSpan.FromSeconds(1));
        }
        catch (Exception ex)
        {
            Console.WriteLine("All retries failed.");
            Console.WriteLine("Final exception type: " + ex.GetType().Name);
        }

        if (success)
        {
            Console.WriteLine("Operation completed successfully.");
        }
    }

    static bool ExecuteWithRetry(Action action, int maxRetries, TimeSpan delay)
    {
        for (int i = 0; i <= maxRetries; i++)
        {
            try
            {
                action();
                return true; // Success
            }
            catch (Exception ex)
            {
                if (i < maxRetries)
                {
                    Console.WriteLine("Failure detected. Exception type: " + ex.GetType().Name);
                    Thread.Sleep(delay);
                }
                else
                {
                    // Last attempt failed, rethrow or handle final failure
                    return false;
                }
            }
        }
        return false; // Should be unreachable if maxRetries >= 0
    }
