  --text-color: #1d1d1f;
  --primary-color: #0a66c2;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #121212;
    --text-color: #e8e8e8;
    --primary-color: #4da3ff;
  }
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
}

.header {
  background-color: var(--bg-color);
  border-bottom: 1px solid rgba(var(--text-color), 0.3);
}
```

